package com.nextrade.engine.market; import com.nextrade.common.identifier.*; import com.nextrade.common.valueobject.*; import java.time.*; public record MarketTick(InstrumentId instrumentId,Price bid,Price ask,Quantity bidSize,Quantity askSize,Instant timestamp){public Price mid(){if(bid==null&&ask==null)return null;if(bid==null)return ask;if(ask==null)return bid;return new Price(bid.value().add(ask.value()).divide(java.math.BigDecimal.valueOf(2),8,java.math.RoundingMode.HALF_EVEN),bid.tickSize());}public boolean crossed(){return bid!=null&&ask!=null&&bid.compareTo(ask)>0;}}
